std::priority_queue<std::pair<double, int>, std::vector<std::pair<double, int>>, std::greater<std::pair<double, int>>> open_set;
std::vector<double> g_score(graph.nodes.size(), std::numeric_limits<double>::infinity());
std::vector<int> came_from(graph.nodes.size(), -1);

g_score[start_idx] = 0.0;
open_set.push({graph.nodes[start_idx].heuristic(graph.nodes[end_idx]), start_idx});

while (!open_set.empty()) {
    int current = open_set.top().second;
    open_set.pop();

    if (current == end_idx) {
        std::vector<Node> path;
        while (current != -1) {
            path.push_back(graph.nodes[current]);
            current = came_from[current];
        }
        std::reverse(path.begin(), path.end());
        return path;
    }

    for (const auto& edge : graph.adj[current]) {
        int neighbor = edge.to;
        double tentative_g_score = g_score[current] + edge.weight;

        if (tentative_g_score < g_score[neighbor]) {
            came_from[neighbor] = current;
            g_score[neighbor] = tentative_g_score;
            double f_score = g_score[neighbor] + graph.nodes[neighbor].heuristic(graph.nodes[end_idx]);
            open_set.push({f_score, neighbor});
        }
    }
}

return std::vector<Node>();
